import json
from dataclasses import dataclass

import boto3
from botocore.exceptions import ClientError
from langchain_core.tools import tool

_s3 = boto3.client("s3")
_SID = "PublicReadForPrefix"


@dataclass
class PolicyResult:
    bucket: str
    resource: str
    statements: int


@tool
def set_bucket_public_read_policy(bucket: str, prefix: str) -> dict:
    try:
        current = json.loads(_s3.get_bucket_policy(Bucket=bucket)["Policy"])
    except ClientError as e:
        if e.response["Error"]["Code"] != "NoSuchBucketPolicy":
            raise
        current = {"Version": "2012-10-17", "Statement": []}
    resource = f"arn:aws:s3:::{bucket}/{prefix.lstrip('/')}*"
    stmts = [s for s in current["Statement"] if s.get("Sid") != _SID]
    stmts.append({
        "Sid": _SID,
        "Effect": "Allow",
        "Principal": "*",
        "Action": "s3:GetObject",
        "Resource": resource,
    })
    current["Statement"] = stmts
    _s3.put_bucket_policy(Bucket=bucket, Policy=json.dumps(current))
    return PolicyResult(bucket, resource, len(stmts)).__dict__

from contextlib import closing

import boto3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("object-storage")


def _client():
    return boto3.client("s3")


@mcp.tool()
def list_bucket_object_sizes(bucket: str, prefix: str = "", max_keys: int = 100) -> dict:
    items = []
    total = 0
    with closing(_client()) as s3:
        paginator = s3.get_paginator("list_objects_v2")
        pages = paginator.paginate(
            Bucket=bucket,
            Prefix=prefix,
            PaginationConfig={"MaxItems": max_keys},
        )
        for page in pages:
            for obj in page.get("Contents", []):
                items.append({"key": obj["Key"], "size": obj["Size"]})
                total += obj["Size"]
    return {"bucket": bucket, "count": len(items), "total_bytes": total, "objects": items}

import json

import boto3
from botocore.exceptions import ClientError
from agents import function_tool

s3 = boto3.client("s3")


@function_tool
def share_prefix_with_account(bucket: str, prefix: str, account_id: str, allow_list: bool = False) -> str:
    if not (account_id.isdigit() and len(account_id) == 12):
        return "error: invalid account id"
    try:
        pol = json.loads(s3.get_bucket_policy(Bucket=bucket)["Policy"])
    except ClientError as e:
        if e.response["Error"]["Code"] != "NoSuchBucketPolicy":
            raise
        pol = {"Version": "2012-10-17", "Statement": []}
    p = prefix.strip("/")
    principal = {"AWS": f"arn:aws:iam::{account_id}:root"}
    sid = f"Share{account_id}"
    pol["Statement"] = [x for x in pol["Statement"] if not x.get("Sid", "").startswith(sid)]
    pol["Statement"].append({
        "Sid": sid + "Get",
        "Effect": "Allow",
        "Principal": principal,
        "Action": "s3:GetObject",
        "Resource": f"arn:aws:s3:::{bucket}/{p}/*",
    })
    if allow_list:
        pol["Statement"].append({
            "Sid": sid + "List",
            "Effect": "Allow",
            "Principal": principal,
            "Action": "s3:ListBucket",
            "Resource": f"arn:aws:s3:::{bucket}",
            "Condition": {"StringLike": {"s3:prefix": [f"{p}/*"]}},
        })
    s3.put_bucket_policy(Bucket=bucket, Policy=json.dumps(pol))
    try:
        t = s3.get_bucket_tagging(Bucket=bucket)["TagSet"]
    except ClientError:
        t = []
    key = f"shared-with-{account_id}"
    t = [x for x in t if x["Key"] != key]
    t.append({"Key": key, "Value": p})
    s3.put_bucket_tagging(Bucket=bucket, Tagging={"TagSet": t})
    return f"shared {bucket}/{p} with {account_id}"

import uuid

import boto3
from langchain_core.tools import tool

s3_control_client = boto3.client("s3control")


@tool
def run_glacier_restore_job(account_id: str, manifest_arn: str, manifest_etag: str, role_arn: str, expiration_days: int) -> str:
    batch_job_response = s3_control_client_call(account_id, manifest_arn, manifest_etag, role_arn, expiration_days)
    return batch_job_response["JobId"]


def s3_control_client_call(account_id, manifest_arn, manifest_etag, role_arn, expiration_days):
    return s3_control_client.create_job(
        AccountId=account_id,
        ConfirmationRequired=False,
        Operation={"S3InitiateRestoreObject": {"ExpirationInDays": expiration_days, "GlacierJobTier": "STANDARD"}},
        Manifest={
            "Spec": {"Format": "S3BatchOperations_CSV_20180820", "Fields": ["Bucket", "Key"]},
            "Location": {"ObjectArn": manifest_arn, "ETag": manifest_etag},
        },
        Report={"Enabled": False},
        Priority=10,
        RoleArn=role_arn,
        ClientRequestToken=str(uuid.uuid4()),
    )
